solutionCodeJson.code:
export type Rect = { w: number; h: number };

// The types are stripped at run time, so the behaviour must be right on its own.
export function area(r: Rect): number {
  return r.w * r.h;
}

import { area } from '../src/area.ts';
const a: number = area({ w: 4, h: 3 });
export { a };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { area } from '../src/area.ts';
test('area multiplies', () => assert.equal(area({ w: 4, h: 3 }), 12));

